// Parse WTO — fix: n8n HTTP node returns string, need JSON.parse
const rawData = $input.item.json;
const parsed = typeof rawData.data === 'string' ? JSON.parse(rawData.data) : (rawData.Dataset ? rawData : rawData.data || rawData);
const dataset = parsed.Dataset || (Array.isArray(parsed) ? parsed : []);

let best = null;
for (const item of dataset) {
  if (item.Value === null || item.Value === undefined) continue;
  const val = parseFloat(item.Value);
  if (isNaN(val)) continue;
  const year = String(item.Year || '0');
  if (!best || year > best.year) {
    best = { year, value: val };
  }
}

const rows = [];
if (best) {
  rows.push({
    source: 'WTO',
    commodity: 'Agricultural Products',
    metric: 'vn_import_tariff_mfn',
    value: best.value,
    unit: '%',
    period: best.year
  });
}

if (rows.length === 0) {
  rows.push({
    source: 'WTO',
    commodity: 'Agricultural Products',
    metric: 'no_data',
    value: 0,
    unit: '%',
    period: 'N/A'
  });
}

return rows.map(r => ({ json: r }));
